from pathlib import Path

path = Path('app/src/main/java/com/mytvb/feature/player/VideoPlayerPlayInfoGateway.kt')
text = path.read_text(encoding='utf-8')

text = text.replace(
    'import okhttp3.Request\n',
    'import okhttp3.Request\n'
    'import okhttp3.HttpUrl.Companion.toHttpUrl\n'
    'import com.google.gson.Gson\n'
    'import com.mytvb.model.BaseResponse\n'
    'import java.security.MessageDigest\n'
)

needle = '''class VideoPlayerPlayInfoGateway(\n    private val apiService: ApiService,\n    private val noCookieApiService: ApiService,\n    private val okHttpClient: OkHttpClient,\n    private val cookieManager: CookieManager,\n    private val sessionGateway: NetworkSessionGateway,\n    private val securityGateway: NetworkSecurityGateway,\n    private val logTag: String\n) {\n'''
replacement = needle + '''\n    private val directPlayInfoClient = OkHttpClient.Builder()\n        .connectTimeout(10, java.util.concurrent.TimeUnit.SECONDS)\n        .readTimeout(15, java.util.concurrent.TimeUnit.SECONDS)\n        .retryOnConnectionFailure(true)\n        .build()\n    private val gson = Gson()\n\n'''
if needle not in text:
    raise SystemExit('class constructor anchor not found')
text = text.replace(needle, replacement, 1)

start_anchor = '''        AppLog.i(\n            logTag,\n            "playback_diag playinfo started cid=$cid qn=$qualityId hasBvid=${resolvedBvid != null}"\n        )\n'''
end_anchor = '''    private suspend fun requestPrimaryPlayInfo(\n'''
start = text.find(start_anchor)
end = text.find(end_anchor, start)
if start < 0 or end < 0:
    raise SystemExit('UGC requestPlayInfo section anchors not found')

new_ugc_section = '''        AppLog.i(\n            logTag,\n            "playback_diag playinfo started cid=$cid qn=$qualityId hasBvid=${resolvedBvid != null} directOnly=true"\n        )\n\n        // Do not touch the Web/WBI playback path for UGC here. The device can play the same\n        // content in other Android/TV clients, so use client-style PlayInfo endpoints first and\n        // keep their request identity isolated from MyTVB's browser emulation.\n        val tvResult = requestTvPlayInfo(\n            aid = aid,\n            cid = cid,\n            qualityId = qualityId,\n            fnval = fnval,\n            fourk = fourk\n        )\n        if (tvResult != null && hasPlayableMedia(tvResult.data)) {\n            AppLog.i(\n                logTag,\n                "playback_diag playinfo winner=tv_api cid=$cid code=${tvResult.code} qn=$qualityId"\n            )\n            return tvResult\n        }\n\n        val appResult = requestAndroidAppPlayInfo(\n            aid = aid,\n            cid = cid,\n            qualityId = qualityId,\n            fnval = fnval,\n            fourk = fourk\n        )\n        if (appResult != null && hasPlayableMedia(appResult.data)) {\n            AppLog.i(\n                logTag,\n                "playback_diag playinfo winner=android_app_api cid=$cid code=${appResult.code} qn=$qualityId"\n            )\n            return appResult\n        }\n\n        val terminal = appResult ?: tvResult ?: PlayInfoResult(\n            code = -1,\n            message = "TV/APP PlayInfo unavailable",\n            data = null\n        )\n        AppLog.w(\n            logTag,\n            "playback_diag playinfo direct_exhausted cid=$cid tvCode=${tvResult?.code} appCode=${appResult?.code} " +\n                "message=${terminal.message}"\n        )\n        return terminal\n    }\n\n    private suspend fun requestTvPlayInfo(\n        aid: Long?,\n        cid: Long,\n        qualityId: Int,\n        fnval: Int,\n        fourk: Int\n    ): PlayInfoResult? = withContext(Dispatchers.IO) {\n        val objectId = aid?.takeIf { it > 0L } ?: return@withContext null\n        var lastResult: PlayInfoResult? = null\n\n        // Both values exist in public TV-client implementations. Try the current documented value\n        // first, then the BBDown-compatible value, without cookies/referrer/browser headers.\n        for (playurlType in listOf("2", "1")) {\n            val url = "https://api.snm0516.aisee.tv/x/tv/playurl".toHttpUrl().newBuilder()\n                .addQueryParameter("object_id", objectId.toString())\n                .addQueryParameter("appkey", "4409e2ce8ffd12b8")\n                .addQueryParameter("build", "106500")\n                .addQueryParameter("cid", cid.toString())\n                .addQueryParameter("device", "android")\n                .addQueryParameter("fnval", fnval.toString())\n                .addQueryParameter("fnver", "0")\n                .addQueryParameter("fourk", fourk.toString())\n                .addQueryParameter("mid", "0")\n                .addQueryParameter("mobi_app", "android_tv_yst")\n                .addQueryParameter("playurl_type", playurlType)\n                .addQueryParameter("platform", "android")\n                .addQueryParameter("qn", qualityId.toString())\n                .build()\n\n            val request = Request.Builder()\n                .url(url)\n                // Keep this deliberately generic. Do not expose a MyTVB/third-party client name.\n                .header("User-Agent", "Mozilla/5.0")\n                .header("Accept", "application/json")\n                .header("Cache-Control", "no-cache")\n                .build()\n\n            val result = runCatching {\n                directPlayInfoClient.newCall(request).execute().use { response ->\n                    if (!response.isSuccessful) {\n                        AppLog.w(\n                            logTag,\n                            "playback_diag tv_playinfo http=${response.code} cid=$cid playurlType=$playurlType"\n                        )\n                        return@use PlayInfoResult(\n                            code = response.code,\n                            message = "TV-API HTTP ${response.code}",\n                            data = null\n                        )\n                    }\n                    parseDirectPlayInfoBody(\n                        body = response.body?.string().orEmpty(),\n                        source = "tv_api",\n                        cid = cid\n                    )\n                }\n            }.onFailure { throwable ->\n                AppLog.w(logTag, "playback_diag tv_playinfo failed cid=$cid msg=${throwable.message}")\n            }.getOrNull()\n\n            if (result != null) {\n                lastResult = result\n                if (hasPlayableMedia(result.data)) return@withContext result\n                if (result.code == 412) return@withContext result\n            }\n        }\n        lastResult\n    }\n\n    private suspend fun requestAndroidAppPlayInfo(\n        aid: Long?,\n        cid: Long,\n        qualityId: Int,\n        fnval: Int,\n        fourk: Int\n    ): PlayInfoResult? = withContext(Dispatchers.IO) {\n        val objectId = aid?.takeIf { it > 0L } ?: return@withContext null\n        val params = linkedMapOf(\n            "appkey" to "1d8b6e7d45233436",\n            "avid" to objectId.toString(),\n            "build" to "7660300",\n            "cid" to cid.toString(),\n            "fnval" to fnval.toString(),\n            "fnver" to "0",\n            "fourk" to fourk.toString(),\n            "mobi_app" to "android",\n            "otype" to "json",\n            "platform" to "android",\n            "qn" to qualityId.toString(),\n            "ts" to (System.currentTimeMillis() / 1000L).toString()\n        )\n        val sign = signAndroidAppParams(params)\n        val urlBuilder = "https://app.bilibili.com/x/v2/playurl".toHttpUrl().newBuilder()\n        params.toSortedMap().forEach { (key, value) ->\n            urlBuilder.addQueryParameter(key, value)\n        }\n        urlBuilder.addQueryParameter("sign", sign)\n\n        val request = Request.Builder()\n            .url(urlBuilder.build())\n            .header(\n                "User-Agent",\n                "Mozilla/5.0 BiliDroid/7.66.0 (bbcallen@gmail.com) os/android model/AndroidTV " +\n                    "mobi_app/android build/7660300 channel/master innerVer/7660310 osVer/6.0 network/2"\n            )\n            .header("Accept", "application/json")\n            .header("Cache-Control", "no-cache")\n            .build()\n\n        runCatching {\n            directPlayInfoClient.newCall(request).execute().use { response ->\n                if (!response.isSuccessful) {\n                    AppLog.w(logTag, "playback_diag android_app_playinfo http=${response.code} cid=$cid")\n                    return@use PlayInfoResult(\n                        code = response.code,\n                        message = "APP-API HTTP ${response.code}",\n                        data = null\n                    )\n                }\n                parseDirectPlayInfoBody(\n                    body = response.body?.string().orEmpty(),\n                    source = "android_app_api",\n                    cid = cid\n                )\n            }\n        }.onFailure { throwable ->\n            AppLog.w(logTag, "playback_diag android_app_playinfo failed cid=$cid msg=${throwable.message}")\n        }.getOrNull()\n    }\n\n    private fun parseDirectPlayInfoBody(\n        body: String,\n        source: String,\n        cid: Long\n    ): PlayInfoResult? {\n        if (body.isBlank()) return null\n        return runCatching {\n            val type = com.google.gson.reflect.TypeToken.getParameterized(\n                BaseResponse::class.java,\n                PlayInfoModel::class.java\n            ).type\n            val parsed: BaseResponse<PlayInfoModel> = gson.fromJson(body, type)\n            AppLog.i(\n                logTag,\n                "playback_diag direct_playinfo source=$source code=${parsed.code} cid=$cid " +\n                    "playable=${hasPlayableMedia(parsed.data)}"\n            )\n            PlayInfoResult(\n                code = parsed.code,\n                message = parsed.errorMessage,\n                data = parsed.data\n            )\n        }.onFailure { throwable ->\n            AppLog.w(logTag, "playback_diag direct_playinfo parse_failed source=$source cid=$cid msg=${throwable.message}")\n        }.getOrNull()\n    }\n\n    private fun signAndroidAppParams(params: Map<String, String>): String {\n        val canonical = params.toSortedMap().entries.joinToString("&") { (key, value) ->\n            "$key=$value"\n        }\n        val digest = MessageDigest.getInstance("MD5").digest(\n            (canonical + "560c52ccd288fed045859ed18bffd973").toByteArray(Charsets.UTF_8)\n        )\n        return digest.joinToString("") { byte ->\n            (byte.toInt() and 0xff).toString(16).padStart(2, '0')\n        }\n    }\n\n'''

text = text[:start] + new_ugc_section + text[end:]

path.write_text(text, encoding='utf-8')
print('Applied clean TV + signed Android App PlayInfo path for UGC; Web/WBI disabled for UGC')
